<!-- @generated by qw-codegen (master_sub) -->
<template>
  <view class="qw-detail qw-stack">
    <template v-if="row">
      <wd-cell-group custom-class="qw-group" border>
        <wd-cell :title="t('field.demo.invoice.invoiceNo')" :value="row.invoiceNo" />
        <wd-cell :title="t('field.demo.invoice.buyer')" :value="row.buyer" />
        <wd-cell :title="t('field.demo.invoice.total')" :value="row.total.toFixed(2)" />
        <wd-cell
          :title="t('field.demo.invoice.issuedAt')"
          :value="row.issuedAt ? formatTime(row.issuedAt) : ''"
        />
        <wd-cell
          :title="t('field.demo.invoice.state')"
          :value="dictText('demo.invoice_state', row.state)"
        />
        <wd-cell
          :title="t('field.common.createdAt')"
          :value="row.createdAt ? formatTime(row.createdAt) : ''"
        />
      </wd-cell-group>
      <view class="qw-sec">
        <text class="qw-sec__title">{{ t('field.demo.invoice.lines') }}</text>
      </view>
      <wd-cell-group
        v-for="(line, i) in row.lines"
        :key="line.id"
        custom-class="qw-group"
        :title="t('crud.rows.row', { n: i + 1 })"
        border
      >
        <wd-cell :title="t('field.demo.invoice.item')" :value="line.item" />
        <wd-cell :title="t('field.demo.invoice.qty')" :value="line.qty" />
        <wd-cell :title="t('field.demo.invoice.unitPrice')" :value="line.unitPrice.toFixed(2)" />
      </wd-cell-group>
      <QwPerm :perm="invoicePerms.modify">
        <wd-button custom-class="qw-btn qw-btn--primary" type="primary" block @click="edit">
          {{ t('crud.action.edit') }}
        </wd-button>
      </QwPerm>
      <QwPerm :perm="invoicePerms.remove">
        <wd-button
          custom-class="qw-btn"
          type="danger"
          variant="plain"
          block
          :loading="removing"
          :disabled="removing"
          @click="remove"
        >
          {{ t('crud.action.delete') }}
        </wd-button>
      </QwPerm>
    </template>
    <QwEmpty v-else-if="error" :title="error" />
  </view>
</template>

<script setup lang="ts">
import { ref, shallowRef } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { type InvoiceDetail, invoicePerms } from '@qiwu/shared'
import { invoiceApi } from '@/api/demo/invoice'
import QwEmpty from '@/core/components/QwEmpty.vue'
import QwPerm from '@/core/components/QwPerm.vue'
import { useDicts } from '@/core/crud'
import { formatTime } from '@/core/format'
import { t } from '@/core/i18n'
import { ApiError, errorText } from '@/core/request'

/**
 * One invoice (mobile, generated): `?id=`; GET /:id answers only a row in the caller's scope (else
 * 404, shown with its message). Showing again (back from its form) reloads it.
 */
const id = ref(0)
const row = shallowRef<InvoiceDetail>()
const error = ref('')
const { dictText } = useDicts(['demo.invoice_state'])

async function load() {
  try {
    row.value = await invoiceApi.get(id.value)
  } catch (e) {
    error.value = errorText(e)
  }
}

onLoad((query) => {
  id.value = Number(query?.id) || 0
  uni.setNavigationBarTitle({ title: t('crud.title.detail', { name: t('demo.invoice.entity') }) })
})
// the first show loads too
onShow(() => void load())

const edit = () => uni.navigateTo({ url: `/pages-biz/demo/invoice/form?id=${id.value}` })

const removing = ref(false)
function remove() {
  uni.showModal({
    title: t('crud.confirm.title'),
    content: t('crud.confirm.delete'),
    confirmText: t('crud.action.delete'),
    cancelText: t('common.action.cancel'),
    success: async ({ confirm }) => {
      if (!confirm || removing.value) return
      removing.value = true
      try {
        await invoiceApi.remove(id.value)
        uni.showToast({ title: t('crud.msg.deleted'), icon: 'none' })
        uni.navigateBack()
      } catch (e) {
        // the request layer toasts a 409 (still in use: a reference, a tree node's children); a row gone
        // meanwhile (404) here
        if (e instanceof ApiError && e.status === 404)
          uni.showToast({ title: e.message, icon: 'none' })
      } finally {
        removing.value = false
      }
    },
  })
}
</script>
